/**
 * Slack Node - Version 2.5
 * Discriminator: resource=channel, operation=close
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** Closes a direct message or multi-person direct message */
export type SlackV25ChannelCloseParams = {
  resource: 'channel';
  operation: 'close';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Slack channel to close
 * @searchListMethod getChannels
 * @default {"mode":"list","value":""}
 */
    channelId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
};

export type SlackV25ChannelCloseNode = {
  type: 'n8n-nodes-base.slack';
  version: 2.5;
  config: NodeConfig<SlackV25ChannelCloseParams> & { credentials?: Credentials };
};